draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw banana
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2 + 70, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw carrot
  ctx.fillStyle = 'orange';
  ctx.beginPath();
  ctx.arc(W/2 - 70, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 80);
  ctx.lineTo(W/2, H/2 - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2 - 30, H/2 - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2 + 30, H/2 - 40);
  ctx.stroke();

  // animate stick figure arm
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 - 40);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2 + 30 + 20 * Math.cos(t), H/2 - 40);
  ctx.stroke();

  ctx.restore();
}
